 noServiceWindow:['Conversation created · no service window','已创建会话 · 未开启服务窗口','Conversa criada · sem janela de serviço'],
 first:['Before conversation creation','未创建会话','Antes de criar a conversa'],
 contactPrompt:['Add PicPay to your contacts?','将 PicPay 添加到联系人？','Adicionar PicPay aos seus contatos?'],
 contactLater:['Not now','以后再说','Agora não'],
 contactShortcut:['Tap to add to contacts','轻触添加到联系人','Toque para adicionar aos contatos'],
