if(p.view==='confirm-block'){title=t('blockConfirm');body='<p class="bt-status-note">'+esc(t('blockExplain'))+'</p>'+btn('block','case-block','danger full')+btn('cancel','case-close','full');}
if(p.view==='report'){title=t('report');body=reportTypes.map((k,i)=>'<label class="pb-setting"><span class="pb-setting-text">'+esc(t(k))+'</span><input type="radio" name="bt-case-report" value="'+i+'"'+(i===(p.reportIndex||0)?' checked':'')+'></label>').join('')+btn('submitReport','case-report-submit','danger full');}
if(p.view==='attachments'){title=t('attach');body=[['gallery','images'],['camera','camera'],['documents','file-text'],['voiceInput','mic'],['inputFavorites','heart'],['changeColor','palette']].map(([k,i])=>caseSetting(t(k),'attach-'+k,i)).join('');}
if(p.view==='composer-picker'){title=t(p.composerKind);const opts=p.composerKind==='gallery'?[['galleryExample','image','service-photo.jpg'],['galleryExample2','image','receipt-example.jpg']]:p.composerKind==='camera'?[['captureExample','image','camera-photo.jpg']]:p.composerKind==='documents'?[['documents','document','service-guide.pdf']]:[];body=opts.map(([label,kind,name])=>btnCase('media-'+kind+'-'+name,t(label))).join('');if(p.composerKind==='inputFavorites')body=p.savedMessage?btnCase('insert-favorite',t('useFavorite')):'<p>'+esc(t('noFavorites'))+'</p>';if(p.composerKind==='changeColor')body=['default','sand','green','blue','rose'].map(c=>btnCase('color-'+c,t('color'+c))).join('');}
if(p.view==='message-menu'){title=t('messageMenu');body=messageMenuBody(true);}
