function colorPicker(){return `<div class="bt-color-picker">${['default','sand','green','blue','rose'].map(key=>`<button type="button" data-action="chat-color-${key}" aria-pressed="${(s.chatColor||'default')===key}"><span class="bt-color-dot bt-color-${key}">${(s.chatColor||'default')===key?ic('check'):''}</span><span>${esc(t('color'+key))}</span></button>`).join('')}</div>`;}
function outgoingMessage(m,i,preview=false){let content=esc(m.key?t(m.key):m.text);if(m.kind==='image')content=`<div class="bt-outgoing-photo">${ic('image')}<span>${esc(t('image'))}</span></div>${m.caption?'<p>'+esc(m.caption)+'</p>':''}`;if(m.kind==='audio')content='<div class="pb-file">'+ic('play')+'<span class="pb-wave"></span>00:08</div>';if(m.kind==='document')content=`<div class="pb-file">${ic('file-text')}<span>${esc(m.name)}<small>PDF · 1.2 MB</small></span></div>${m.caption?'<p>'+esc(m.caption)+'</p>':''}`;return `<div class="pb-bubble out" data-business-message data-message-kind="${m.kind||'text'}">${m.quote?'<div class="pb-quote"><strong>'+esc(NAME)+'</strong><br>'+esc(t(m.quoteKey||'sampleReply'))+'</div>':''}${content}${time(true,m.failed)}${m.failed&&!preview?'<button type="button" class="pb-link" data-action="retry-'+i+'">'+esc(t('retry'))+'</button>':''}</div>`;}
function businessChannel(){if(!available()||s.blocked||!s.channelLinked)return top(t('channel'),'profile')+`<div class="pb-unavailable">${ic('megaphone')}<p>${esc(t('channelUnavailable'))}</p></div>`;return `<div class="pb-top"><button type="button" class="pb-icon" data-action="go-profile" aria-label="${esc(t('back'))}">${ic('arrow-left')}</button>${avatar()}<span class="pb-chat-name"><span>PicPay · ${esc(t('channel'))}</span><small>${esc(t('broadcastUpdates'))}</small></span><button type="button" class="pb-icon" data-action="channel-mute" aria-label="${esc(t(s.channelMuted?'unmute':'mute'))}">${ic(s.channelMuted?'bell-off':'bell')}</button></div><div class="bt-channel-body"><div class="bt-channel-identity"><strong>PicPay · ${esc(t('channel'))}</strong><p>${esc(t('channelDescription'))}</p></div><div class="pb-date">${esc(t('today'))}</div><article class="bt-channel-post"><h3>${esc(t('broadcastTitle'))}</h3><p>${esc(t('broadcastBody'))}</p><span class="pb-time">09:20</span></article><article class="bt-channel-post"><h3>${esc(t('broadcastTitle2'))}</h3><p>${esc(t('broadcastBody2'))}</p><button type="button" class="pb-link" data-action="channel-post">${esc(t('readMorePreview'))}</button><span class="pb-time">09:35</span></article></div><div class="bt-channel-readonly">${ic('megaphone')}<span>${esc(t('broadcastOnly'))}</span></div>`;}

function contextDetails(){
 const business=overlay==='list-menu';
 const item=business?{name:available()?s.alias||NAME:t('unavailable'),unread:s.unread,muted:s.muted,favorited:s.favorited}:sampleData(sampleRows.find(x=>x.id===selectedSample));
 const prefix=business?'':'sample-';
 return {business,item,actions:[
  [item.unread?'read':'unread',prefix+'read','message-square-check'],
  ['archive',prefix+'archive','archive'],
  [item.muted?'unmute':'mute',prefix+'mute','bell-off'],
  [item.favorited?'unfavorite':'favorite',prefix+'favorite','heart'],
  ['delete',business?'delete':'sample-delete','trash-2']
 ]};
}
function contextPreview(business,item){
 let content='';
 if(business){
  if(firstContact&&!s.cleared)content='<div class="pb-bubble">'+esc(t('billText'))+time()+'</div>';else if(s.seed&&!s.cleared){content=`<div class="pb-bubble out">${esc(t('sampleUser'))}${time(true)}</div>`;
   if(s.showReply)content+=s.blocked||!available()?`<div class="pb-bubble">${esc(t('textReply'))}${time()}</div>`:messageCard();}
  content+=s.messages.slice(-2).map((m,i)=>outgoingMessage(m,i,true)).join('');
 }else if(item.type==='channel'){
  content=`<div class="pb-bubble"><strong>${esc(t('channelPreview'))}</strong><p>${esc(t('channelContextBody'))}</p><span class="pb-time">09:15</span></div><div class="pb-bubble"><strong>${esc(t('channelContextTitle'))}</strong><p>${esc(t('channelContextMore'))}</p><span class="bt-preview-link">${esc(t('readMorePreview'))}</span><span class="pb-time">09:20</span></div>`;
 }else{
  content=`<div class="pb-bubble${item.type==='personal'?' out':''}">${esc(t(item.type==='group'?'groupContextEarlier':'personalContextEarlier'))}<span class="pb-time">09:30</span></div><div class="pb-bubble">${item.previewIcon==='mic'?ic('mic')+' ':''}${esc(t(item.preview))}<span class="pb-time">${item.time==='yesterday'?esc(t('yesterday')):item.time}</span></div>`;
 }
 if(!content)content='<div class="pb-emptychat">'+esc(t('emptyChats'))+'</div>';
 // The preview reuses message visuals but never exposes message actions.
 content=content.replace(/\sdata-action="[^"]*"/g,'');
 return `<section class="bt-context-preview" aria-label="${esc(t('conversationPreview'))}"><div class="bt-context-title"><span data-tooltip="${esc(item.name)}">${esc(item.name)}</span>${business?badge():''}</div><div class="bt-context-thread" inert>${content}</div></section>`;
}
function contextMarkup(){
 const {business,item,actions}=contextDetails();
 return `<button type="button" class="bt-context-dismiss" data-action="close" aria-label="${esc(t('close'))}"></button>${contextPreview(business,item)}<div class="bt-context-menu">${actions.map(([key,action,icon])=>`<button type="button" class="cursor-interaction${key==='delete'?' bt-context-danger':''}" data-action="${action}"><span>${esc(t(key))}</span>${ic(icon)}</button>`).join('')}</div>`;
}
function renderListContext(){
 const node=document.createElement('div');node.className='bt-context-overlay';node.setAttribute('role','dialog');node.setAttribute('aria-modal','true');node.setAttribute('aria-label',t('longpress'));
 node.innerHTML=contextMarkup();screen.appendChild(node);
 requestAnimationFrame(()=>node.querySelector('.bt-context-menu button')?.focus());
}

