root.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||el.disabled)return;if(el.dataset.language){s.lang=el.dataset.language;render();remember();return;}if(el.dataset.page){leaveFirstContact();return go(el.dataset.page);}if(el.dataset.review&&['rules','messages'].includes(el.dataset.review)){s.review=el.dataset.review;renderNotes();remember();return;}if(el.dataset.action)act(el.dataset.action);});
root.addEventListener('input',e=>{if(e.target.id==='bt-contact-name'){(s.page==='cases'?pc():s).contactDraft=e.target.value;return;}if(e.target.id==='bt-profile-search-input'){const isCase=e.target.dataset.caseSearch==='true';if(isCase)pc().profileQuery=e.target.value;else s.profileQuery=e.target.value;q('#bt-profile-search-results').innerHTML=profileSearchResults(isCase);return;}if(e.target.id==='case-compose'){pc().draft=e.target.value;updateComposerActions(true);}if(e.target.id==='bt-compose'){draft=e.target.value;updateComposerActions(false);}if(e.target.id==='bt-search'){s.query=e.target.value;const pos=e.target.selectionStart;render();q('#bt-search')?.focus();q('#bt-search')?.setSelectionRange(pos,pos);}});
root.addEventListener('change',e=>{
if(e.target.id==='bt-summary-kind'||e.target.id==='bt-summary-receipt'){s.listPreview??={kind:'text',direction:'in',receipt:'sent'};if(e.target.id==='bt-summary-kind')s.listPreview.kind=e.target.value;else{s.listPreview.direction=e.target.value==='in'?'in':'out';s.listPreview.receipt=e.target.value;}render();remember();return;}
if(e.target.id==='bt-push-kind'){s.pushKind=e.target.value;renderNotes();return;}
if(e.target.dataset.caseOption!==undefined){pc().topic=Number(e.target.dataset.caseOption);render();return;}if(e.target.id==='case-select'){phaseCaseAction('case-select-'+e.target.value);return;}if(e.target.name==='bt-topic'){topicDraft=e.target.value;render();return;}if(e.target.id==='bt-access-path'){const value=e.target.value;leaveFirstContact();if(value==='h5')beginH5Visit();else if(value==='installed')act('entry-installed');else if(value==='signed-out')act('entry-login');else{s.accessPath='in-app';go('list');}return;}if(e.target.id==='pb-state'){selectPreviewState(e.target.value);return;}if(e.target.id==='bt-format'){leaveFirstContact();s.format=e.target.value;s.selected='';s.cardExpired=false;s.showReply=true;s.seed=true;s.cleared=false;if(!s.blocked&&available()){s.session='active';s.retained=true;s.conversationCreated=true;}go('chat');}if(e.target.dataset.toggle==='muted'){s.muted=e.target.checked;record('muteExplain');remember();}if(e.target.dataset.toggle==='locked'){if(e.target.checked){e.target.checked=false;sheet('lock');}else{s.locked=false;record('lockExplain');remember();}}});
root.addEventListener('keydown',e=>{if((e.key==='ContextMenu'||e.shiftKey&&e.key==='F10')&&e.target.matches('[data-notice-report]')){e.preventDefault();return openBusinessMessageMenu(e.target);}if(s.page==='cases'&&e.key==='Enter'&&e.target.id==='case-compose'){e.preventDefault();return phaseCaseAction('case-send');}if(s.page==='cases'&&e.key==='Escape'&&pc().view){e.preventDefault();return phaseCaseAction('case-close');}if(e.key==='Enter'&&e.target.id==='bt-compose'){e.preventDefault();send(e.target.value);}if(e.key==='Escape'&&overlay){overlay='';render();}if(e.key==='Tab'&&(overlay||s.page==='cases'&&['consent','source-controls','menu','controls','receiving','list','confirm-block','confirm-unblock','report','attachments','file','message-menu','theme','lock','clear','saved-messages'].includes(pc().view))){const all=[...screen.querySelectorAll('.pb-sheet button:not(:disabled),.pb-sheet input,.bt-context-menu button,.bt-context-dismiss,.bt-attach-menu button,.bt-attach-dismiss,.bt-more-panel button:not(:disabled),.bt-more-dismiss')],first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
let messageReportAction='';
function openBusinessMessageMenu(message){
 messageReportAction=message.dataset.noticeReport||'';messageMenuKind=message.dataset.messageKind||(message.querySelector?.('.bt-document-card')?'document':'text');
 if(s.page==='cases')phaseCaseAction('case-message-menu');
 else sheet('message-menu');
}
root.addEventListener('contextmenu',e=>{
 const message=e.target.closest('[data-case-business-message],[data-business-message]');
 if(message){e.preventDefault();openBusinessMessageMenu(message);return;}
 const row=e.target.closest('[data-sample-id]');
 if(row){e.preventDefault();selectedSample=row.dataset.sampleId;sheet('sample-list');return;}
 if(e.target.closest('#pb-business-row')){e.preventDefault();sheet('list-menu');}
});
let pressOrigin=null,pressFired=false;
root.addEventListener('click',e=>{if(pressFired&&!e.target.closest('.bt-context-menu,.pb-sheet')){e.preventDefault();e.stopImmediatePropagation();pressFired=false;}},true);
root.addEventListener('pointerdown',e=>{
 clearTimeout(longPress);pressFired=false;pressOrigin={x:e.clientX,y:e.clientY};
 if(e.button!==0)return;
 
 const sample=e.target.closest('[data-sample-id]');
 const business=e.target.closest('#pb-business-row');
 const message=e.target.closest('[data-case-business-message],[data-business-message]');
 if(sample||business||message&&!e.target.closest('button'))longPress=setTimeout(()=>{
  pressFired=true;
  if(sample){selectedSample=sample.dataset.sampleId;sheet('sample-list');}
  else if(business)sheet('list-menu');
  else openBusinessMessageMenu(message);
 },650);
});
root.addEventListener('pointermove',e=>{if(pressOrigin&&Math.hypot(e.clientX-pressOrigin.x,e.clientY-pressOrigin.y)>8)clearTimeout(longPress);});
['pointerup','pointercancel'].forEach(type=>root.addEventListener(type,()=>{clearTimeout(longPress);pressOrigin=null;}));

function bindSwipe(){const el=q('#pb-business-row');if(!el)return;let start;el.addEventListener('pointerdown',e=>{start={x:e.clientX,y:e.clientY};});el.addEventListener('pointerup',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>55&&Math.abs(dy)<35){s.swipe=dx>0?'right':'left';el.addEventListener('click',x=>{x.preventDefault();x.stopPropagation();},{capture:true,once:true});setTimeout(render,0);remember();}});}
function hydrate(snapshot){const p=snapshot?.privateContent;
if(p?.schema===10&&p.current?.state){if(languages[p.language]!==undefined)s.lang=p.language;if(['rules','messages'].includes(p.review))s.review=p.review;restoreScenario(p.current);firstContact=!!p.firstContact;firstNormalSnapshot=p.normal||null;firstDemoSnapshot=p.first||null;if(p.samples)Object.assign(sampleState,p.samples);return;}if(![6,7,8,9].includes(p?.schema))return;if(languages[p.language]!==undefined)s.lang=p.language;if(['list','chat','profile','search','contacts','h5','login','invalid','business-channel','download'].includes(p.page))s.page=p.page;s.review=['rules','messages'].includes(p.review)?p.review:'rules';if(['in-app','installed','signed-out','h5'].includes(p.accessPath))s.accessPath=p.accessPath;if(['ready','installed','failed'].includes(p.installStage))s.installStage=p.installStage;if(['ios','android'].includes(p.downloadPlatform))s.downloadPlatform=p.downloadPlatform;if(typeof p.handoffValid==='boolean')s.handoffValid=p.handoffValid;if(formats.includes(p.format))s.format=p.format;if(modes.includes(p.mode))mode(p.mode);if(s.page==='list'&&['list-menu','sample-list'].includes(p.context)){if(sampleRows.some(x=>x.id===p.contextItem))selectedSample=p.contextItem;overlay=p.context==='sample-list'&&!selectedSample?'list-menu':p.context;}}
