const reportTypes=['reasonFake','reasonSpam','reasonFraud','reasonHarm','reasonPrivacy','reasonOther'];
function accessHub(){return top(t('accessHub'),'list')+`<div class="bt-group">${row('searchBusiness','go-search','search')}${row('notInstalled','launch-uninstalled','download')}${row('coldLaunch','launch-cold','power')}${row('warmLaunch','launch-warm','smartphone')}${row('notLogged','launch-signed-out','log-in')}</div>`;}
function startExternalVisit(kind){leaveFirstContact();clearTimeout(downloadTimer);s.accessPath='h5';s.externalLaunch=kind;s.h5GenericEntry=false;s.installStage=kind==='uninstalled'?'ready':'installed';s.handoffTarget=HANDLE;s.handoffValid=true;s.invalidReason='';go('h5');record('h5Visit',{launch:kind,target:HANDLE,destination:'profile',conversation_created:false});}
function finishExternalVisit(){if(!available()||!s.handoffValid||s.handoffTarget!==HANDLE){s.invalidReason=!available()?'business':'token';go('invalid');return;}s.profileReturnPage='access-hub';go('profile');record('returnHelp',{launch:s.externalLaunch||'cold',target:HANDLE,destination:'profile',profile_variant:s.conversationCreated?'full':'simple',auto_send:false,consent_created:false,window_created:false});}
function defaultAvatar(large=false){return `<span class="pb-avatar bt-default-avatar${large?' large':''}" role="img" aria-label="${esc(ct('默认商业号头像','Default business avatar','Avatar comercial padrão'))}">${ic('store')}</span>`;}
function contactForm(isCase=false){const name=isCase?phaseCasesData.CO[phaseCasesData.SC[pc().id].co].n:NAME;const val=isCase?pc().contactDraft:s.contactDraft;return `<div class="bt-contact-form">${isCase?caseAvatar(true):avatar(true)}<strong>${esc(name)}</strong><label>${esc(t('contactName'))}<input id="bt-contact-name" value="${esc(val??name)}" maxlength="80" autocomplete="off"></label><p>${esc(t('contactSaveHelp'))}</p>${(isCase?pc().contactError:s.contactError)?'<p role="alert">'+esc(t(isCase?pc().contactError:s.contactError))+'</p>':''}${btn('saveContactAction',isCase?'case-confirm-save-contact':'confirm-save-contact','primary full')}${btn('cancel',isCase?'case-close':'close','full')}</div>`;}
function confirmSaveContact(isCase=false){const p=isCase?pc():s,name=(q('#bt-contact-name')?.value??p.contactDraft??(isCase?phaseCasesData.CO[phaseCasesData.SC[p.id].co].n:NAME)).trim();p.contactDraft=name;if(!name){p.contactError='contactNameRequired';render();return;}if(s.mode==='offline'){p.contactError='contactSaveFailed';render();return;}p.contactError='';p.saved=true;if(isCase){caseMerchant().saved=true;caseMerchant().contactName=name;p.view=p.profileReturn?'profile':'';if(phaseCasesData.SC[p.id].co==='picpay'){s.saved=true;s.alias=name;}}else{s.alias=name;s.contactPromptDismissed=true;syncMainManagementFlags();overlay='';}render();record('contactSaved',{prototype_only:true,consent_changed:false});toast('contactSaved');remember();}
function voiceRecorder(isCase=false){const p=isCase?pc():s,prefix=isCase?'case-':'';return `<div class="bt-voice-recorder">${ic('mic')}<p role="status">${esc(t(p.voiceStage==='recording'?'voiceRecording':p.voiceStage==='ready'?'voiceReady':'voicePreview'))}</p>${p.voiceStage==='recording'?btn('voiceStop',prefix+'voice-stop','primary full'):p.voiceStage==='ready'?btn('voiceUse',prefix+'voice-use','primary full'):btn('voiceStart',prefix+'voice-start','primary full')}${btn('cancel',isCase?'case-close':'close','full')}</div>`;}
function messageMenuBody(isCase=false){const media=['image','audio','document','template_image','template_document'].includes(messageMenuKind);if(isCase)return caseSetting(t('quote'),'quote','reply')+(!media?caseSetting(t('copy'),'copy-message','copy'):'')+caseSetting(t('saveMessage'),'save-message','star')+(media?caseSetting(t('saveMedia'),'save-media','download'):'')+caseSetting(t('report'),messageReportAction==='case-utility-report'?'utility-report':'report','flag',true);return row('quote','quote','reply','','',false,s.blocked||!available())+(!media?row('copy','copy','copy'):'')+row('saveMessage','save-message','star')+(media?row('saveMedia','save-media','download'):'')+row('report',messageReportAction||'report','flag','','',true);}
function receiptMark(outgoing,failed=false,read=false){if(!outgoing)return '';return `<span class="bt-receipt${read&&!failed?' is-read':''}" aria-label="${esc(ct(failed?'发送失败':read?'已读':'已发送',failed?'Failed':read?'Read':'Sent',failed?'Falha':read?'Lida':'Enviada'))}">${ic(failed?'circle-alert':read?'check-check':'check')}</span>`;}
function summaryByKind(kind,text=''){const k=kind?.replace('template_','');return ['image','audio','document','video'].includes(k)?t(k==='video'?'videoUnsupported':k)+(text?' · '+text:''):text||t(kind?.startsWith('template_')?'summaryTemplate':'newMessage');}
function listReceipt(){const last=s.messages.at(-1);return s.listPreview?receiptMark(s.listPreview.direction==='out',false,s.listPreview.receipt==='read'):receiptMark(!!last,last?.failed,s.receiptPreview==='read');}
function pushPreviewText(kind,text=''){return text.trim()||({text:ct('商家给你发来一条消息','The business sent you a message','A empresa enviou uma mensagem'),image:ct('你收到一张图片','You received an image','Você recebeu uma imagem'),audio:ct('你收到一条语音消息','You received a voice message','Você recebeu uma mensagem de voz'),document:ct('你收到一个文件','You received a document','Você recebeu um arquivo'),template_text:ct('你收到一条通知','You received a notification','Você recebeu uma notificação'),template_image:ct('你收到一条图片通知','You received an image notification','Você recebeu uma notificação com imagem'),template_document:ct('你收到一条文件通知','You received a document notification','Você recebeu uma notificação com arquivo')})[kind]||t('newMessage');}
function meetingPushPreview(){if(s.blocked||s.muted)return `<p class="bt-status-note">${esc(ct('已静音或屏蔽，不展示 Push。','Muted or blocked: no Push preview.','Silenciada ou bloqueada: sem Push.'))}</p>`;return `<div class="bt-phiz-push"><span class="bt-phiz-push-icon">${ic('message-circle')}</span><span class="bt-phiz-push-content"><span class="bt-phiz-push-meta">PhizChat <span>${esc(ct('现在','now','agora'))}</span></span><strong>PicPay</strong><span>${esc(pushPreviewText(s.pushKind||s.format))}</span></span></div>`;}
function meetingReview(){return `<details class="bt-meeting-review" open><summary>${esc(ct('11/13 会议范围与待确认项','Nov 13 scope and pending decisions','Escopo de 13/11 e decisões pendentes'))}</summary><ul><li>${esc(ct('本期基础消息：文本、图片、语音、文件；模板：文本、图片、文件＋按钮。视频不支持。','This phase: text, image, voice and document messages; text, image and document templates with buttons. No video.','Nesta fase: texto, imagem, voz e arquivo; modelos de texto, imagem e arquivo com botões. Sem vídeo.'))}</li><li>${esc(ct('认证只有显示/不显示徽标；列表是否统一展示、接口字段待确认。审核状态仅用于预览，不展示给用户。','Verification is badge or no badge. List consistency and the API field need confirmation; review states are preview-only.','Verificação: com ou sem selo. Consistência na lista e campo da API pendentes; estados de análise só na prévia.'))}</li><li>${esc(ct('John：补齐文件类型、大小与格式明细。通讯录服务端负责人：确认添加联系人接口是否复用。','John: document formats and size limits. Contacts backend owner: confirm reuse of the add-contact API.','John: formatos e limites de arquivos. Responsável pelo servidor de contatos: confirmar reutilização da API.'))}</li><li>${esc(t('sharePendingBody'))}</li><li>${esc(ct('举报类型为交互候选，需与冠创团队同步最终枚举；安全性说明是交互文案，需确认实际服务方案，不承诺端到端加密。','Report types are UI candidates pending alignment with Guanchuang’s team. Security copy needs validation against the actual service; it does not claim end-to-end encryption.','Tipos de denúncia são candidatos, pendentes com a equipe de Guanchuang. O texto de segurança depende do serviço real; não afirma criptografia de ponta a ponta.'))}</li><li>${esc(ct('普通账号不能向商业号转发消息。本轮长按保留回复、按内容复制/保存、收藏、举报。','Personal accounts cannot forward messages to business accounts. Long press retains reply, content-appropriate copy/save, favorite and report.','Contas pessoais não podem encaminhar para contas comerciais. Toque longo mantém resposta, copiar/salvar conforme o conteúdo, favoritos e denúncia.'))}</li></ul></details>`;}
function meetingControls(){const kinds=['text','image','audio','document','template_text','template_image','template_document'];return `<section class="bt-meeting-controls"><strong>${esc(ct('11/13 场景预览','Nov 13 previews','Prévias de 13/11'))}</strong><div class="pc-actions">${btn('accessHub','go-access-hub')}${btn('dualConsentPreview','meeting-dual-consent')}<button type="button" class="pb-button" data-action="preview-avatar">${esc(ct('默认头像','Default avatar','Avatar padrão'))}</button></div>${s.page==='list'?`<label>${esc(ct('摘要类型','Summary type','Tipo de resumo'))}<select id="bt-summary-kind">${kinds.map(k=>`<option value="${k}"${s.listPreview?.kind===k?' selected':''}>${esc(t(k))}</option>`).join('')}</select></label><label>${esc(ct('收发与回执','Direction and receipt','Direção e recibo'))}<select id="bt-summary-receipt"><option value="in"${s.listPreview?.direction!=='out'?' selected':''}>${esc(ct('收到 · 不显示勾','Incoming · no tick','Recebida · sem marca'))}</option><option value="sent"${s.listPreview?.receipt==='sent'?' selected':''}>${esc(ct('发出 · 单勾','Outgoing · one tick','Enviada · uma marca'))}</option><option value="read"${s.listPreview?.receipt==='read'?' selected':''}>${esc(ct('已读 · 双蓝勾','Read · blue double tick','Lida · duas marcas azuis'))}</option></select></label>`:''}<label>Push<select id="bt-push-kind">${kinds.concat('unknown').map(k=>`<option value="${k}"${(s.pushKind||s.format)===k?' selected':''}>${esc(k==='unknown'?ct('无法识别','Unrecognized','Não reconhecida'):t(k))}</option>`).join('')}</select></label>${meetingPushPreview()}</section>`;}
function launchingPage(){return '<div class="bt-launching" role="status">'+h5AppIcon()+'<strong>PhizChat</strong><p>'+esc(ct('正在打开商户主页…','Opening the business profile…','Abrindo o perfil da empresa…'))+'</p></div>';}
function formatOptions(){return [[ct('本期基础消息','This-phase basic messages','Mensagens básicas desta fase'),['text','image','audio','document']],[ct('本期模板','This-phase templates','Modelos desta fase'),['template_text','template_image','template_document']],[ct('其他已有设计示例（本次不确认范围）','Other design examples (scope not confirmed here)','Outros exemplos (escopo não confirmado aqui)'),['reply_button','list','cta_url','mini_program','rich_card','carousel','voice_call']]].map(([title,items])=>'<optgroup label="'+esc(title)+'">'+items.map(f=>'<option value="'+f+'"'+(s.format===f?' selected':'')+'>'+esc(t(f==='list'?'listFormat':f))+'</option>').join('')+'</optgroup>').join('');}
let messageMenuKind='text';

function composerBar(isCase,value,media){const p=isCase?pc():s,prefix=isCase?'case-':'',ready=!!(String(value||'').trim()||media),panel=p.composerPanel;return `<div class="bt-composer-shell"><div class="pb-composer"><button type="button" class="pb-icon bt-composer-plus" data-action="${prefix}composer-attachments" aria-label="${esc(t('attach'))}" aria-expanded="${panel==='attachments'}">${ic(panel==='attachments'?'x':'plus')}</button><span class="pb-inputwrap"><input id="${isCase?'case':'bt'}-compose" aria-label="${esc(t('input'))}" value="${esc(value||'')}"><button type="button" class="pb-composer-tool" data-action="${prefix}composer-emoji" aria-label="${esc(ct('表情','Emoji','Emoji'))}" aria-expanded="${panel==='emoji'}">${ic('sticker')}</button><button type="button" class="pb-composer-tool" data-action="${isCase?'case-composer-camera':'camera-picker'}" aria-label="${esc(t('camera'))}">${ic('camera')}</button></span><button type="button" class="pb-icon bt-composer-voice" data-action="${prefix}voice-picker" aria-label="${esc(t('voiceInput'))}"${ready?' hidden':''}>${ic('mic')}</button><button type="button" class="pb-icon pb-send" data-action="${prefix}send" aria-label="${esc(t('send'))}"${ready?'':' hidden'}>${ic('send')}</button></div>${panel==='attachments'?'<div class="bt-composer-panel bt-composer-grid" role="group" aria-label="'+esc(t('attach'))+'">'+attachmentItems.map(([key,action,icon])=>'<button type="button" data-action="'+(isCase?'case-composer-pick-'+key:action)+'"><span class="bt-attachment-icon">'+ic(icon)+'</span><span>'+esc(t(key))+'</span></button>').join('')+'</div>':panel==='emoji'?'<div class="bt-composer-panel bt-emoji-grid" role="group" aria-label="'+esc(ct('表情','Emoji','Emoji'))+'">'+['😀','🙂','👍','❤️','🙏','🎉','😊','✅'].map((e,i)=>'<button type="button" data-action="'+prefix+'composer-insert-'+i+'" aria-label="'+esc(e)+'">'+e+'</button>').join('')+'</div>':''}</div>`;}
function updateComposerActions(isCase){const value=isCase?pc().draft:draft,media=isCase?pc().draftMedia:draftMedia,ready=!!(String(value||'').trim()||media),prefix=isCase?'case-':'';const mic=q('[data-action="'+prefix+'voice-picker"]'),sendButton=q('[data-action="'+prefix+'send"]');if(mic)mic.hidden=ready;if(sendButton)sendButton.hidden=!ready;}
function handleComposerAction(action,isCase){const prefix=isCase?'case-':'',p=isCase?pc():s;if(!action.startsWith(prefix+'composer-')&&!(isCase&&['case-remove-draft','case-insert-favorite'].includes(action))&&!(isCase&&action.startsWith('case-media-')))return false;if(p.blocked||(!isCase&&!available())){toast('unavailableHelp');return true;}if(isCase&&q('#case-compose'))p.draft=q('#case-compose').value;const key=action.slice(prefix.length);if(key==='composer-attachments'||key==='composer-emoji'){const wanted=key==='composer-attachments'?'attachments':'emoji';p.composerPanel=p.composerPanel===wanted?'':wanted;render();return true;}if(key.startsWith('composer-insert-')){const emoji=['😀','🙂','👍','❤️','🙏','🎉','😊','✅'][Number(key.slice(16))];if(emoji){if(isCase)p.draft=(p.draft||'')+emoji;else draft+=emoji;}render();return true;}if(isCase){p.composerPanel='';if(key==='composer-camera'||key.startsWith('composer-pick-')){p.composerKind=key==='composer-camera'?'camera':key.slice(14);p.view='composer-picker';}else if(action==='case-remove-draft')p.draftMedia=null;else if(action==='case-insert-favorite'){p.draft=t('textReply');p.view='';}else if(action.startsWith('case-media-')){const [,kind,name]=action.match(/^case-media-(image|document)-(.*)$/)||[];if(kind)p.draftMedia={kind,name};p.view='';}render();return true;}return false;}
root.addEventListener('focusin',e=>{if(['bt-compose','case-compose'].includes(e.target.id)){const p=e.target.id==='case-compose'?pc():s;p.composerPanel='';const shell=e.target.closest?.('.bt-composer-shell');shell?.querySelector('.bt-composer-panel')?.remove();shell?.querySelectorAll('[aria-expanded]').forEach(x=>x.setAttribute('aria-expanded','false'));const plus=shell?.querySelector('.bt-composer-plus');if(plus){plus.innerHTML=ic('plus');if(globalThis.lucide)lucide.createIcons({attrs:{width:18,height:18}});}}});

