let versionsOpen=false;
function releaseText(x){return x?.[s.lang]||x?.zh||'';}
function versionHistoryHTML(){const d=releaseHistoryData,url='https://github.com/johnsun180406-netizen/business-account-interactive-review';return '<p class="bt-version-policy">'+esc(releaseText(d.versionPolicy))+'</p>'+d.entries.map((r,i)=>'<details class="bt-version-entry"'+(i===0?' open':'')+'><summary><span>v'+r.version+'</span> '+esc(releaseText(r.title))+' <small>'+esc(r.date)+'</small></summary><p><b>'+esc(ct('影响范围','Impact','Impacto'))+'：</b>'+esc(releaseText(r.impact))+'</p><ul>'+r.changes.map(x=>'<li>'+esc(releaseText(x))+'</li>').join('')+'</ul><p><b>'+esc(ct('验证','Validation','Validação'))+'：</b>'+esc(releaseText(r.validation))+'</p><p><b>'+esc(ct('待办／适用说明','Pending / applicability','Pendências / aplicação'))+'：</b>'+esc(releaseText(r.pending))+'</p>'+(r.commit?'<div class="bt-version-links"><a target="_blank" rel="noopener" href="'+url+'/commit/'+r.commit+'">'+esc(ct('查看该版提交','View commit','Ver commit'))+'</a> '+(d.entries[i+1]?.commit?'<a target="_blank" rel="noopener" href="'+url+'/compare/'+d.entries[i+1].commit+'...'+r.commit+'">'+esc(ct('对比上一版','Compare previous','Comparar anterior'))+'</a>':'')+'</div>':'')+'</details>').join('')+'<details class="bt-version-legacy"><summary>'+esc(ct('更早提交记录（保留原始标题）','Earlier commits (original titles)','Commits anteriores (títulos originais)'))+'</summary><ul>'+d.legacyCommits.map(r=>'<li>'+esc(r.date.slice(0,10))+' <a target="_blank" rel="noopener" href="'+url+'/commit/'+r.sha+'">'+esc(r.title)+'</a></li>').join('')+'</ul></details>';}
function renderVersionHistory(){const d=releaseHistoryData,latest=d.entries[0];q('#bt-version-button').textContent='v'+d.currentVersion+' · '+ct('版本记录','Version history','Histórico');q('#bt-version-button').setAttribute('aria-expanded',String(versionsOpen));q('#bt-version-panel').hidden=!versionsOpen;if(versionsOpen)q('#bt-version-panel').innerHTML='<div class="bt-version-head"><h3>'+esc(ct('版本记录','Version history','Histórico de versões'))+'</h3><span>'+esc(latest.date)+' · '+ct('设计稿','Design','Design')+'</span></div>'+versionHistoryHTML();}

hydrate(window.openai?.widgetState);render();window.addEventListener('openai:set_globals',e=>{const w=e.detail?.globals?.widgetState;if(w&&JSON.stringify(w.privateContent)!==savedKey){hydrate(w);render();}});
